css:
/* Brochure library: one heading, then a titled group of PDF cards per series.
   Every group and card comes from the `groups` prop, so a new series or a new
   document is a list row, not a copied subtree. */
.bz-section[data-bz-node="lib"]{background:#fff;padding-block:clamp(56px,7vw,96px)}
[data-bz-node="lib"] .bz-block{padding-block:0}
[data-bz-node="lib-h"] h2{margin-bottom:var(--space-5)}

[data-bz-node^="lib-group"]{margin-bottom:clamp(28px,3.4vw,44px)}
[data-bz-node="lib-groups"]>.bz-col:last-child{margin-bottom:0}
[data-bz-node^="lib-ghead"]{align-items:end;margin-bottom:var(--space-3)}
[data-bz-node^="lib-gtitle"] h3{font:700 clamp(1rem,1.5vw,1.25rem)/1.2 var(--font-heading);letter-spacing:0;margin:0;color:var(--ink)}
[data-bz-node^="lib-gmeta"] .bz-text p{margin:0;text-align:right;font:700 .625rem/1.4 var(--font-body);letter-spacing:.16em;text-transform:uppercase;color:var(--muted)}

/* Cards: three across on desktop, two on tablet, one on a phone. */
[data-bz-node^="lib-docs"]{grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}
[data-bz-node^="lib-docs"]>.bz-col{grid-column:auto}
[data-bz-node^="lib-doc"] .bz-block{padding:0}
[data-bz-node^="lib-doc"] .bz-btns{margin:0}
[data-bz-node^="lib-doc"] .bz-btn{display:flex;width:100%;justify-content:space-between;align-items:center;gap:16px;min-height:62px;padding:0 24px;background:#fff;border:1px solid var(--line);border-radius:0;color:var(--ink);font:700 .75rem/1.3 var(--font-body);letter-spacing:.02em;text-transform:none;transition:border-color .18s ease,box-shadow .18s ease,transform .18s ease}
[data-bz-node^="lib-doc"] .bz-btn::after{content:"PDF \2192";width:auto;height:auto;background:none;-webkit-mask:none;mask:none;flex:none;font:700 .625rem/1 var(--font-body);letter-spacing:.14em;color:var(--muted);transition:color .18s ease,transform .18s ease}
[data-bz-node^="lib-doc"] .bz-btn:hover{border-color:var(--ink);box-shadow:0 8px 22px rgba(0,0,0,.07);transform:translateY(-1px)}
[data-bz-node^="lib-doc"] .bz-btn:hover::after{color:var(--ink);transform:translateX(3px)}

@media (max-width:1100px){[data-bz-node^="lib-docs"]{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media (max-width:640px){
  [data-bz-node^="lib-docs"]{grid-template-columns:1fr}
  [data-bz-node^="lib-ghead"]{row-gap:6px}
  [data-bz-node^="lib-gtitle"],[data-bz-node^="lib-gmeta"]{grid-column:1/-1}
  [data-bz-node^="lib-gmeta"] .bz-text p{text-align:left}
}
